async def cmd_baul_digital(update: Update, context: ContextTypes.DEFAULT_TYPE) -> None:
    """Consulta o guarda una nota rápida en el Baúl Digital (/baul o /baul Título: Contenido)."""
    msg = update.effective_message
    user = update.effective_user
    if not msg or not user:
        return
    import bot_agenda_cea
    bot_agenda_cea._guardar_config_agenda(chat_id=str(msg.chat_id))
    resto = " ".join(context.args).strip() if context.args else ""
    if resto:
        partes = resto.split(":", 1)
        tit = partes[0].strip()
        cont = partes[1].strip() if len(partes) > 1 else resto
        bot_agenda_cea.guardar_item_baul(
            tit, cont, categoria="NOTA TELEGRAM", origen="Bot Telegram CEA", notificar_tg=False
        )
        await _enviar_mensaje_seguro(
            context.bot,
            chat_id=msg.chat_id,
            text=f"🗄️ ✅ *Guardado en tu Baúl Digital y sincronizado en la Web:*\n📌 *{tit}*",
            reply_markup=teclado_agenda_baul_bot(user.id),
            reply_to_message_id=msg.message_id,
        )
        return
    await _enviar_mensaje_seguro(
        context.bot,
        chat_id=msg.chat_id,
        text=bot_agenda_cea._formatear_texto_baul(),
        reply_markup=teclado_agenda_baul_bot(user.id),
        reply_to_message_id=msg.message_id,
    )


def _loop_keep_alive() -> None:
    while True:
        time.sleep(600)
        if RENDER_EXTERNAL_URL:
            try:
                url_ping = f"{RENDER_EXTERNAL_URL.rstrip('/')}/health"
                urllib.request.urlopen(url_ping, timeout=15).read()
            except Exception:
                try:
                    urllib.request.urlopen(RENDER_EXTERNAL_URL, timeout=15).read()
                except Exception:
                    pass


def iniciar_servidor_healthcheck() -> None:
    """
    UNIFICACIÓN TRIPLE EN RENDER ($7 USD/mes):
    En el puerto web de este servicio activo (bot-clases-autooriente), levanta automáticamente:
    1. El Dashboard Web Completo de Auditoría Contable y Cartera (app_web_auditor.py).
    2. El Demonio de Recordatorios Automáticos y Agenda Google Calendar + Baúl Digital (bot_agenda_cea.py).
    3. El Keep-Alive cada 10 minutos.
    """
    os.environ["UNIFIED_MAIN_BOT_ACTIVE"] = "1"
    try:
        import bot_agenda_cea
        bot_agenda_cea.iniciar_daemon_agenda_telegram()
        logger.info("📅 Demonio de Agenda Google Calendar + Recordatorios activo.")
    except Exception as exc_ag:
        logger.warning("Aviso iniciando demonio de agenda: %s", exc_ag)

    try:
        import app_web_auditor
        server = app_web_auditor.ThreadingHTTPServer(("0.0.0.0", PORT), app_web_auditor.AuditorWebHandler)
        hilo = threading.Thread(target=server.serve_forever, daemon=True)
        hilo.start()
        hilo_ping = threading.Thread(target=_loop_keep_alive, daemon=True)
        hilo_ping.start()
        logger.info("🌐 Sistema Web de Auditoría Contable + Agenda + Clases activo en puerto %s", PORT)
        return
    except Exception as exc_web:
        logger.warning("Fallback a HealthCheckHandler básico (%s)", exc_web)

    try:
        server = HTTPServer(("0.0.0.0", PORT), HealthCheckHandler)
        hilo = threading.Thread(target=server.serve_forever, daemon=True)
        hilo.start()
        hilo_ping = threading.Thread(target=_loop_keep_alive, daemon=True)
        hilo_ping.start()
        logger.info("🌐 Servidor Health Check + Keep-Alive activo en puerto %s", PORT)
    except Exception as exc:
        logger.warning("No se pudo iniciar servidor Health Check: %s", exc)


def main() -> None:
    if not TELEGRAM_BOT_TOKEN or TELEGRAM_BOT_TOKEN == "TU_TELEGRAM_BOT_TOKEN":
        logger.error("⚠️ Configura TELEGRAM_BOT_TOKEN en .env o en Render.")
        sys.exit(1)

    iniciar_servidor_healthcheck()
    threading.Thread(target=sheets_service.limpiar_nombres_contaminados, daemon=True).start()

    app = ApplicationBuilder().token(TELEGRAM_BOT_TOKEN).build()
    app.add_handler(CommandHandler(["start", "ayuda", "help"], cmd_ayuda))
    app.add_handler(CommandHandler(["panel", "admin", "administrador"], cmd_panel_admin))
    app.add_handler(CommandHandler(["cierres", "agenda_practica"], cmd_cierres_admin))
    app.add_handler(CommandHandler(["agenda", "calendario", "mi_agenda", "eventos"], cmd_agenda_calendario))
    app.add_handler(CommandHandler(["baul", "notas"], cmd_baul_digital))
    app.add_handler(CommandHandler(["soy", "instructor", "mi_nombre"], cmd_registrar_instructor))
    app.add_handler(CommandHandler(["alumno", "matricular"], cmd_registrar_alumno))
    app.add_handler(CommandHandler(["clase", "menu", "registrar"], cmd_menu_clase))
    app.add_handler(CommandHandler(["mis_clases", "misclases", "clases"], cmd_mis_clases))
    app.add_handler(CommandHandler(["nomina", "liquidacion", "clases_instructor"], cmd_nomina_admin))
    app.add_handler(CommandHandler("alertas", cmd_alertas_admin))
    app.add_handler(CommandHandler("supervisar", cmd_supervisar_admin))
    app.add_handler(CommandHandler(["inasistencia", "inasistencias", "falla", "fallas"], cmd_inasistencias))
    app.add_handler(CommandHandler(["mantenimiento", "mantenimientos", "manteniminto", "mantenimintos", "taller", "pesv"], cmd_mantenimientos))
    app.add_handler(CommandHandler("inicializar", cmd_inicializar))
    app.add_handler(CommandHandler("reporte", cmd_reporte))

    app.add_handler(CallbackQueryHandler(manejar_botones_callback))
    app.add_handler(MessageHandler(filters.PHOTO | filters.Document.IMAGE, procesar_mensaje_imagen))
    app.add_handler(MessageHandler(filters.TEXT & (~filters.COMMAND), procesar_texto_chat))

    logger.info("🚗 Bot CEA Auto Oriente iniciado...")
    app.run_polling(drop_pending_updates=False)


if __name__ == "__main__":
    main()
